  useEffect(() => { let cancelled = false; if (!navigator.storage?.persisted) return () => { cancelled = true; }; void navigator.storage.persisted().then((isPersistent) => { if (!cancelled) setPersistenceStatus(isPersistent ? "Persistent storage is enabled for this site." : "This site is using best-effort browser storage."); }).catch(() => { if (!cancelled) setPersistenceStatus("Browser storage persistence status is unavailable."); }); return () => { cancelled = true; }; }, []);
  useEffect(() => { let cancelled = false; const createdUrls: string[] = []; const load = async () => { const photos = data.progressPhotos ?? []; const entries = await Promise.all(photos.filter((x) => !x.deletedAt).map(async (x) => { const item = await readPhotoBlob(String(x.blobKey)); if (!item) return null; const url = URL.createObjectURL(item.blob); createdUrls.push(url); return [String(x.id), url] as const; })); if (!cancelled) setPhotoUrls(Object.fromEntries(entries.filter((entry): entry is readonly [string, string] => !!entry))); else createdUrls.forEach((url) => URL.revokeObjectURL(url)); }; void load(); return () => { cancelled = true; createdUrls.forEach((url) => URL.revokeObjectURL(url)); }; }, [data.progressPhotos]);
  const run = async (action: () => Promise<unknown>, success = "Saved successfully.") => { setBusy(true); setStatus("Saving…"); try { await action(); await reload(); setStatus(success); } catch (error) { setStatus(error instanceof Error ? error.message : "Save failed; existing records were preserved."); } finally { setBusy(false); } };
