  const onJsonFile = async (file?: File) => { if (!file) return; try { if (file.size > 50_000_000) throw Error("JSON backups larger than 50 MB are not supported."); const parsed = JSON.parse(await file.text()) as unknown; const checked = validateProgressBackup(parsed), existing = await readProgressOverview(); const summary = Object.entries(checked.validated).map(([store, rows]) => { const currentIds = new Set((existing[store as keyof typeof existing] ?? []).map((row) => String(row.id))); const duplicates = rows.filter((row) => currentIds.has(String((row as { id?: unknown }).id))).length; return { store, incoming: rows.length, conflicts: duplicates }; }); setRestorePreview({ backup: checked.backup, summary }); setStatus("Backup validated. Review incoming counts and conflicts, then choose a restore mode."); } catch (error) { setStatus(error instanceof Error ? error.message : "Invalid backup; no records were changed."); } };
