    {page.startsWith("analytics/") && page !== "analytics/data-quality" && <section className="progress-card" aria-label="Analytics date range"><h2>Inclusive date range</h2><label>Range<select value={analyticsPreset} onChange={(event) => setAnalyticsPreset(event.target.value)}><option value="7">7 days</option><option value="28">28 days</option><option value="84">12 weeks</option><option value="180">6 months</option><option value="365">1 year</option><option value="all">All recorded time</option><option value="custom">Custom</option></select></label>{analyticsPreset === "custom" && <><label>From date<input type="date" value={customFrom} onChange={(event) => setCustomFrom(event.target.value)} /></label><label>Through date<input type="date" value={customTo} onChange={(event) => setCustomTo(event.target.value)} /></label></>}<p>Showing {analyticsWindow.from} through {analyticsWindow.to}, inclusive.</p></section>}
