      {page === "progress" && <section className="progress-card"><h2>Private progress records</h2><div className="progress-stat-grid">{[["Weight", weights.length], ["Circumference", live("circumferenceSessions").length], ["External reports", live("bodyCompositionMeasurements").length], ["Photos", live("progressPhotos").length], ["Goals", live("progressGoals").length], ["Nutrition days reviewed", live("nutritionDayReviews").length]].map(([label, value]) => <article key={String(label)}><h3>{String(label)}</h3><p>{String(value)} records</p></article>)}</div><a href="/progress/weight">Open body measurements</a></section>}
